import { getJson, postJson } from '../../api/http';
import { sheetKey } from '../sheet/api';

/** A person's plan: an amount, a start date, every N days or else a day of the month (1 to 31), an end
 *  date, how many claims it has made so far and (when listed) its next dates: the first five plan dates after
 *  the sheet's today and on or before the end. */
export type Plan = { id: number; sheetId: string; personId: number; amount: string; start: string; every: number | null; day: number | null; end: string; by: string; generated: number; nextDates?: string[] };

export type PlanInput = { amount: string; start: string; every: string; day: string; end: string };

export type GenerateResult = { made: number };

const sheetBase = (sheetId: string) => `/api/sheets/${encodeURIComponent(sheetId)}`;

export const plansKey = (sheetId: string) => [...sheetKey(sheetId), 'plans'] as const;

/** The sheet's plans, in the order they were added. */
export function listPlans(sheetId: string): Promise<Plan[]> {
  return getJson<Plan[]>(`${sheetBase(sheetId)}/plans`);
}

/** Give the person a plan; refused (rejects) for an amount the claim form would refuse, an interval that is
 *  not a whole number of at least 1, a day of the month not 1 to 31 (or both or neither given), or an end before the start. */
export function addPlan(sheetId: string, by: string, personId: number, input: PlanInput): Promise<Plan> {
  return postJson<Plan>(`${sheetBase(sheetId)}/people/${personId}/plans?by=${encodeURIComponent(by)}`, input);
}

/** Make the DRAFT claims every plan is due up to its end and the sheet's today, that it has not made yet. */
export function generatePlans(sheetId: string, by: string): Promise<GenerateResult> {
  return postJson<GenerateResult>(`${sheetBase(sheetId)}/generate-plans?by=${encodeURIComponent(by)}`, {});
}
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { useSubmitOnce } from '../../forms/useSubmitOnce';
import { claimsKey } from '../claims/api';
import { generatePlans, plansKey } from './api';

/** A button that makes the claims every plan is due (see `generatePlans`), and how many it made. The
 *  count is cleared while it runs; a refused generate makes nothing and shows an error. */
export function GeneratePlans({ sheetId, user }: { sheetId: string; user: string }) {
  const queryClient = useQueryClient();
  const submitOnce = useSubmitOnce();

  const generate = useMutation({
    mutationFn: () => generatePlans(sheetId, user),
    // Not awaited: the count shows as soon as the generate is done, never after its new rows.
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
      void queryClient.invalidateQueries({ queryKey: plansKey(sheetId) });
    },
  });

  return (
    <section>
      <button type="button" data-testid="plan-generate" disabled={generate.isPending}
        onClick={() => submitOnce(() => {
          generate.reset();
          return generate.mutateAsync();
        })}>
        Generate plan claims
      </button>
      {generate.isSuccess && (
        <>
          {' '}Made <span data-testid="plan-generated-count">{generate.data.made}</span>
        </>
      )}
      {generate.isError && (
        <span data-testid="plan-generate-error">The plans' claims could not be generated.</span>
      )}
    </section>
  );
}
import { useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { useSubmitOnce } from '../../forms/useSubmitOnce';
import { addPlan, listPlans, plansKey, type PlanInput } from './api';
import { Fig } from '../session/Fig';

const EMPTY: PlanInput = { amount: '', start: '', every: '', day: '', end: '' };

/** A person's plans (each its amount, start, every N days or day of the month, end, how many claims it has made so far and its next dates)
 *  and a form that adds one; a refused add shows an error on the row and adds nothing. */
export function PersonPlans({ sheetId, user, personId }: { sheetId: string; user: string; personId: number }) {
  const queryClient = useQueryClient();
  const plans = useQuery({ queryKey: plansKey(sheetId), queryFn: () => listPlans(sheetId) });
  const [form, setForm] = useState<PlanInput>(EMPTY);
  const submitOnce = useSubmitOnce();

  const add = useMutation({
    mutationFn: (input: PlanInput) => addPlan(sheetId, user, personId, input),
    onSuccess: () => {
      setForm(EMPTY);
      return queryClient.invalidateQueries({ queryKey: plansKey(sheetId) });
    },
  });

  const change = (patch: Partial<PlanInput>) => {
    setForm((f) => ({ ...f, ...patch }));
    add.reset();
  };

  return (
    <div>
      Plans
      <table>
        <tbody>
          {(plans.data ?? []).filter((pl) => pl.personId === personId).map((pl) => (
            <tr key={pl.id} data-testid={`plan-row-${pl.id}`}>
              <td data-testid="plan-amount-shown"><Fig>{Number(pl.amount).toFixed(2)}</Fig></td>
              <td data-testid="plan-start">{pl.start}</td>
              {pl.day != null
                ? <td>monthly on day <span data-testid="plan-day">{pl.day}</span></td>
                : <td>every <span data-testid="plan-every">{pl.every}</span> days</td>}
              <td>to <span data-testid="plan-end">{pl.end}</span></td>
              <td>made <span data-testid="plan-generated">{pl.generated}</span></td>
              <td>next <span data-testid="plan-next-dates">{(pl.nextDates ?? []).join(', ')}</span></td>
            </tr>
          ))}
        </tbody>
      </table>
      <form
        onSubmit={(e) => {
          e.preventDefault();
          const input = form;
          submitOnce(() => {
            add.reset();
            return add.mutateAsync(input);
          });
        }}
      >
        <input data-testid="plan-form-amount" placeholder="Amount" value={form.amount}
          onChange={(e) => change({ amount: e.target.value })} />{' '}
        <input type="date" data-testid="plan-form-start" value={form.start}
          onChange={(e) => change({ start: e.target.value })} />{' '}
        <input data-testid="plan-form-every" placeholder="Every N days" value={form.every}
          onChange={(e) => change({ every: e.target.value })} />{' '}
        <input data-testid="plan-form-day" placeholder="or day of month" value={form.day}
          onChange={(e) => change({ day: e.target.value })} />{' '}
        <input type="date" data-testid="plan-form-end" value={form.end}
          onChange={(e) => change({ end: e.target.value })} />{' '}
        <button type="submit" data-testid="plan-form-submit" disabled={add.isPending}>
          Add plan
        </button>
        {add.isError && (
          <span data-testid="plan-error">A plan needs an amount of 0.00 or more with up to two decimals, a start, either every a whole number of days (at least 1) or a day of the month (1 to 31), and an end not before the start.</span>
        )}
      </form>
    </div>
  );
}
import { SheetBody } from '../../slots/defs/sheetBody';
import { GeneratePlans } from './GeneratePlans';

export const contribution = SheetBody.fill({ order: 9.8, Component: GeneratePlans });
