package net.officefloor.hq.app.plan;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Pauses the plan from the sheet's today (PLAN_PAUSED); pausing a paused plan is refused. */
public class PausePlan {
    public void pause(@RequestParam(name = "by", required = false) String by, @Val Plan plan,
            @Val Person person, PlanRepository plans, SheetRepository sheets, Audit audit)
            throws InvalidPlanException {
        if (plan.paused()) throw new InvalidPlanException("The plan is already paused");
        plans.pause(plan.id(), sheets.today(plan.sheetId()));
        audit.record("PLAN_PAUSED sheet=" + plan.sheetId() + " by=" + (by == null ? "" : by)
                + " name=" + person.getName() + " start=" + plan.start());
    }
}
EOF
cat > $D/ResumePlan.java <<'EOF'
package net.officefloor.hq.app.plan;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Resumes the paused plan from the sheet's today (PLAN_RESUMED); resuming a running plan is refused. */
public class ResumePlan {
    public void resume(@RequestParam(name = "by", required = false) String by, @Val Plan plan,
            @Val Person person, PlanRepository plans, SheetRepository sheets, Audit audit)
            throws InvalidPlanException {
        if (!plan.paused()) throw new InvalidPlanException("The plan is not paused");
        plans.resume(plan.id(), sheets.today(plan.sheetId()));
        audit.record("PLAN_RESUMED sheet=" + plan.sheetId() + " by=" + (by == null ? "" : by)
                + " name=" + person.getName() + " start=" + plan.start());
    }
}
EOF
R="src/main/resources/officefloor/rest/api/sheets/{sheetId}/plans/{planId}"; mkdir -p "$R"
for a in pause resume; do C=$([ $a = pause ] && echo PausePlan || echo ResumePlan); W=$([ $a = pause ] && echo "pause the plan from the sheet's today; pausing a paused plan is refused" || echo "resume the paused plan from the sheet's today; resuming a running plan is refused"); cat > "$R/$a.POST.yml" <<EOF
# POST /api/sheets/{sheetId}/plans/{planId}/$a — $W.
# A plan date on or after the day paused and before the day resumed is skipped, not postponed.
# A viewer may change nothing: refused before anything is read or written.
guard:
  class: net.officefloor.hq.app.setting.RefuseViewer
  next: load
load:
  class: net.officefloor.hq.app.plan.LoadPlan
  govern: [ transaction ]
  next: $a
$a:
  class: net.officefloor.hq.app.plan.$C
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.plan.RespondWithPlan
EOF
done; cat "$R/resume.POST.yml"

